/**
 * WhatAuth CDN Client SDK
 * Carga automática sin configuración obligatoria más allá de los atributos data-* o whatauth.config.js
 */

(function (root, factory) {
  if (typeof define === 'function' && define.amd) {
    define([], factory);
  } else if (typeof module === 'object' && module.exports) {
    module.exports = factory();
  } else {
    root.WhatAuth = factory();
  }
}(typeof self !== 'undefined' ? self : this, function () {
  'use strict';

  // Constantes de configuración por defecto
  const DEFAULTS = {
    wsUrl: (typeof window !== 'undefined' && (window.location.hostname === 'localhost' || window.location.hostname === '127.0.0.1'))
      ? 'http://localhost:3000'
      : 'https://api.whatauth.com',
    apiKey: '',
    domain: '',
    storage: 'sessionStorage', // 'sessionStorage' | 'httpOnly'
    authEndpoint: '',          // Solo requerido si storage === 'httpOnly'
    redirectUrl: '',           // URL de redirección opcional
    qrId: 'whatauth-qr',
    linkId: 'whatauth-link',
    expiredId: 'whatauth-expired',
    statusId: 'whatauth-status',
    pinId: 'whatauth-pin',
    sessionDuration: 300       // 5 minutos (en segundos)
  };

  /**
   * Cargar Socket.IO dinámicamente si no está presente en la ventana
   */
  function ensureSocketIO(callback) {
    if (typeof window.io === 'function') {
      return callback(null, window.io);
    }
    const script = document.createElement('script');
    script.src = 'https://cdn.socket.io/4.8.1/socket.io.min.js';
    script.async = true;
    script.onload = () => {
      if (typeof window.io === 'function') {
        callback(null, window.io);
      } else {
        callback(new Error('Socket.IO loaded but io is not defined'));
      }
    };
    script.onerror = () => callback(new Error('Failed to load Socket.IO from CDN'));
    document.head.appendChild(script);
  }

  // Captura inmediata y síncrona del script en el momento exacto en que se ejecuta este archivo
  const executedScriptElement = (typeof document !== 'undefined' && document.currentScript) ? document.currentScript : null;

  /**
   * Extraer configuración desde la etiqueta <script> ejecutada
   */
  function getScriptConfig() {
    if (typeof document === 'undefined') return {};

    // 1. Usar el script capturado síncronamente al evaluar el archivo
    let targetScript = executedScriptElement;

    // 2. Si no estuviera disponible, buscar el script específico que incluye atributos WhatAuth
    if (!targetScript) {
      targetScript = document.querySelector('script[data-api-key], script[data-key]') ||
                     document.querySelector('script[src*="whatauth"]') ||
                     document.currentScript;
    }

    // 3. Fallback: último script de la página
    if (!targetScript) {
      const scripts = document.getElementsByTagName('script');
      targetScript = scripts[scripts.length - 1];
    }

    if (!targetScript) return {};

    const dataset = targetScript.dataset || {};
    const config = {};

    const mapping = {
      apiKey: dataset.apiKey || dataset.key || targetScript.getAttribute('data-api-key') || targetScript.getAttribute('data-key'),
      wsUrl: dataset.wsUrl || targetScript.getAttribute('data-ws-url'),
      domain: dataset.domain || targetScript.getAttribute('data-domain'),
      storage: dataset.storage || targetScript.getAttribute('data-storage'),
      authEndpoint: dataset.authEndpoint || targetScript.getAttribute('data-auth-endpoint'),
      redirectUrl: dataset.redirectUrl || targetScript.getAttribute('data-redirect-url'),
      qrId: dataset.qrId || targetScript.getAttribute('data-qr-id'),
      linkId: dataset.linkId || targetScript.getAttribute('data-link-id'),
      expiredId: dataset.expiredId || targetScript.getAttribute('data-expired-id'),
      statusId: dataset.statusId || targetScript.getAttribute('data-status-id'),
      pinId: dataset.pinId || targetScript.getAttribute('data-pin-id')
    };

    // Solo asignar claves que contengan valor explícito no vacío para no anular los DEFAULTS
    Object.keys(mapping).forEach(key => {
      if (mapping[key] !== null && mapping[key] !== undefined && mapping[key] !== '') {
        config[key] = mapping[key];
      }
    });

    return config;
  }

  class WhatAuthClient {
    constructor(userOptions = {}) {
      const scriptOpts = getScriptConfig();
      const globalOpts = (typeof window !== 'undefined' && window.WHATAUTH_CONFIG) ? window.WHATAUTH_CONFIG : {};

      // Fusión de prioridades: DEFAULTS < window.WHATAUTH_CONFIG < scriptOpts < userOptions
      this.options = Object.assign({}, DEFAULTS, globalOpts, scriptOpts, userOptions);

      // Si el dominio no fue especificado, inferir el host actual
      if (!this.options.domain && typeof window !== 'undefined') {
        this.options.domain = window.location.host || 'localhost';
      }

      this.socket = null;
      this.session = null;
      this.expirationTimer = null;
      this.listeners = {};
    }

    on(event, cb) {
      if (!this.listeners[event]) this.listeners[event] = [];
      this.listeners[event].push(cb);
      return this;
    }

    emit(event, data) {
      // Disparar listeners registrados en la instancia
      if (this.listeners[event]) {
        this.listeners[event].forEach(cb => {
          try { cb(data); } catch (e) { console.error('[WhatAuth SDK] Error in listener:', e); }
        });
      }
      // Disparar evento DOM estándar
      if (typeof window !== 'undefined') {
        window.dispatchEvent(new CustomEvent(`whatauth:${event}`, { detail: data }));
      }
    }

    init() {
      if (!this.options.apiKey) {
        console.error('[WhatAuth SDK] ❌ Falta el parámetro "apiKey" o el atributo "data-api-key" en el script.');
        return;
      }

      ensureSocketIO((err, io) => {
        if (err) {
          console.error('[WhatAuth SDK] Error cargando Socket.IO:', err);
          this.emit('error', err);
          return;
        }

        this.connect(io);
      });
    }

    connect(io) {
      const { wsUrl, apiKey, domain } = this.options;

      this.updateStatus('Conectando...');

      const resolvedDomain = domain || (typeof window !== 'undefined' ? (window.location.host || window.location.hostname || 'localhost') : 'localhost');

      this.socket = io(wsUrl, {
        auth: {
          key: apiKey,
          domain: resolvedDomain,
          origin: (typeof window !== 'undefined' && window.location.origin && window.location.origin !== 'null') ? window.location.origin : ''
        },
        query: {
          domain: resolvedDomain
        },
        extraHeaders: {
          'x-api-key': apiKey,
          'x-whatauth-domain': resolvedDomain
        },
        transports: ['websocket', 'polling']
      });

      this.socket.on('connect', () => {
        this.updateStatus('Conectado. Solicitando QR...');
        this.emit('connected', { socketId: this.socket.id });
        // Solicitar el QR outside automáticamente
        this.socket.emit('req_outside_qr_auth', {
          key: apiKey,
          domain: resolvedDomain
        });
      });

      this.socket.on('res_outside_qr_auth', (data) => {
        this.session = data;
        this.bindQrToDOM(data);
        this.startExpirationTimer(data.expiresIn || this.options.sessionDuration);
        this.emit('qr', data);
      });

      this.socket.on('outside_auth_success', async (data) => {
        this.clearExpirationTimer();
        this.updateStatus('¡Autenticado con éxito!');
        this.emit('success', data);

        // Procesar modo de almacenamiento configurado
        await this.handleStorageSuccess(data);
      });

      this.socket.on('outside_auth_error', (data) => {
        console.error('[WhatAuth SDK] ❌ outside_auth_error:', data);
        this.updateStatus(`Error: ${data.error || 'No autorizado'}`);
        this.emit('error', data);
      });

      this.socket.on('disconnect', (reason) => {
        this.updateStatus('Desconectado');
        this.emit('disconnected', { reason });
      });
    }

    bindQrToDOM(data) {
      const { qrId, linkId, pinId, expiredId } = this.options;

      // 1. Ocultar cualquier cartel de expirado previo
      const elExpired = document.getElementById(expiredId);
      if (elExpired) {
        elExpired.style.display = 'none';
      }

      // 2. Pintar imagen QR
      const elQr = document.getElementById(qrId);
      if (elQr) {
        const qrSrc = data.qrBase64 || data.qrDataUrl || data.qrUrlData || '';
        if (elQr.tagName === 'IMG') {
          elQr.src = qrSrc;
        } else {
          elQr.style.backgroundImage = `url("${qrSrc}")`;
          elQr.style.backgroundSize = 'contain';
          elQr.style.backgroundRepeat = 'no-repeat';
        }
        elQr.style.display = '';
      }

      // 3. Pintar Walink
      const elLink = document.getElementById(linkId);
      if (elLink) {
        if (elLink.tagName === 'A') {
          elLink.href = data.walink || '#';
          elLink.target = '_blank';
        } else {
          elLink.onclick = () => window.open(data.walink, '_blank');
        }
        elLink.style.display = '';
      }

      // 4. Pintar PIN si el usuario puso un contenedor
      const elPin = document.getElementById(pinId);
      if (elPin && data.pin) {
        elPin.textContent = data.pin;
      }

      this.updateStatus('Listo para escanear');
    }

    startExpirationTimer(seconds) {
      this.clearExpirationTimer();
      this.expirationTimer = setTimeout(() => {
        this.handleExpiration();
      }, seconds * 1000);
    }

    clearExpirationTimer() {
      if (this.expirationTimer) {
        clearTimeout(this.expirationTimer);
        this.expirationTimer = null;
      }
    }

    handleExpiration() {
      const { expiredId, qrId, linkId } = this.options;

      // 1. Mostrar elemento de expirado si existe
      const elExpired = document.getElementById(expiredId);
      if (elExpired) {
        elExpired.style.display = '';
      }

      // 2. Opcionalmente atenuar el QR
      const elQr = document.getElementById(qrId);
      if (elQr) {
        elQr.style.opacity = '0.2';
      }

      const elLink = document.getElementById(linkId);
      if (elLink) {
        elLink.style.pointerEvents = 'none';
        elLink.style.opacity = '0.5';
      }

      this.updateStatus('QR Expirado');
      this.emit('expired', { session: this.session });
    }

    updateStatus(text) {
      const elStatus = document.getElementById(this.options.statusId);
      if (elStatus) {
        elStatus.textContent = text;
      }
    }

    async handleStorageSuccess(data) {
    const { storage, authEndpoint, redirectUrl } = this.options;
    const candidateToken = data.token || data.sessionId;
    const candidatePhone = data.phone || (data.user && data.user.phone) || "";
    const candidateName = data.name || (data.user && data.user.name) || "";
    const candidateDomain = data.domain || this.options.domain || "";
    const candidateSessionId = data.sessionId || candidateToken;

    if (storage === "sessionStorage" && typeof sessionStorage !== "undefined") {
      try {
        sessionStorage.setItem("whatauth_token", candidateToken);
        sessionStorage.setItem("whatauth_user", JSON.stringify({
          phone: candidatePhone,
          name: candidateName,
          lid: data.lid,
          domain: candidateDomain,
          sessionId: candidateSessionId,
          user: data.user || { phone: candidatePhone, name: candidateName }
        }));
        console.log("[WhatAuth SDK] 💾 Token JWT guardado en sessionStorage (whatauth_token)");
      } catch (e) {
        console.warn("[WhatAuth SDK] No se pudo guardar en sessionStorage:", e);
      }
    }

    if (storage === "httpOnly" && authEndpoint && typeof fetch !== "undefined") {
      try {
        this.updateStatus("Estableciendo sesión segura...");
        const resp = await fetch(authEndpoint, {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          credentials: "include",
          body: JSON.stringify({
            token: candidateToken,
            phone: candidatePhone,
            name: candidateName,
            domain: candidateDomain,
            sessionId: candidateSessionId,
            user: data.user || { phone: candidatePhone, name: candidateName }
          })
        });

        if (!resp.ok) {
          console.error("[WhatAuth SDK] Error en POST a " + authEndpoint + ":", resp.status, resp.statusText);
          this.emit("authEndpointError", { status: resp.status });
        } else {
          console.log("[WhatAuth SDK] 🔒 Sesión httpOnly enviada con éxito a " + authEndpoint);
          this.emit("authEndpointSuccess", await resp.json().catch(() => ({})));
        }
      } catch (err) {
        console.error("[WhatAuth SDK] Falló la petición a " + authEndpoint + ":", err);
        this.emit("authEndpointError", { error: err.message });
      }
    }

    // Redirección condicional: SÓLO si el desarrollador configuró explícitamente options.redirectUrl
    const targetRedirect = redirectUrl;
    if (targetRedirect && typeof targetRedirect === "string" && typeof window !== "undefined" && targetRedirect !== window.location.href && targetRedirect !== window.location.origin) {
      setTimeout(() => {
        window.location.href = targetRedirect;
      }, 500);
    }
  }

  }

  // Auto-inicialización inmediata al cargar el script en el DOM
  if (typeof window !== 'undefined') {
    const autoInit = () => {
      const client = new WhatAuthClient();
      window.whatAuthClient = client;
      // Auto-iniciar si tiene API Key configurada
      if (client.options.apiKey) {
        client.init();
      }
    };

    if (document.readyState === 'loading') {
      document.addEventListener('DOMContentLoaded', autoInit);
    } else {
      autoInit();
    }
  }

  return WhatAuthClient;
}));
